class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None
def insert(root, value):
    if root is None:
        return Node(value)
    current = root
    while True:
        if value < current.value:
            if current.left is None:
                current.left = Node(value)
                break
            current = current.left
        else:
            if current.right is None:
                current.right = Node(value)
                break
            current = current.right
    return root
def height(node):
    if node is None:
        return 0
    return 1 + max(height(node.left), height(node.right))
def range_audit(node, low, high):
    if node is None:
        return 0, 0
    total, count = (node.value, 1) if low <= node.value <= high else (0, 0)
    if node.value > low:
        child_sum, child_count = range_audit(node.left, low, high)
        total, count = total + child_sum, count + child_count
    if node.value <= high:
        child_sum, child_count = range_audit(node.right, low, high)
        total, count = total + child_sum, count + child_count
    return total, count
