        i = (start + step) % 11
        if state[i] == 0:
            return -1
        if state[i] == 1 and keys[i] == key:
            return i
    return -1
def free_slot(key):
    start = key % 11
    first_tombstone = -1
    for step in range(11):
        i = (start + step) % 11
        if state[i] == 2 and first_tombstone < 0:
            first_tombstone = i
        if state[i] == 0:
            return first_tombstone if first_tombstone >= 0 else i
    return first_tombstone
def ensure_outgoing(pair):
    incoming, outgoing = pair
    if not outgoing:
        while incoming:
            outgoing.append(incoming.pop())
