import sys

def valid_code(code):
    return 4 <= len(code) <= 8 and all(ch in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789' for ch in code)

def parse_ticket(line):
    pieces = line.split()
    if len(pieces) != 2 or not valid_code(pieces[0]):
        return None
    try:
        priority = int(pieces[1])
    except ValueError:
        return None
    if not 1 <= priority <= 5:
        return None
    return pieces[0], priority

def intake(lines):
    seen = set()
    accepted = []
    rejected = 0
    for line in lines:
        ticket = parse_ticket(line)
        if ticket is None or ticket[0] in seen:
            rejected += 1
            continue
        seen.add(ticket[0])
        accepted.append(ticket)
    return sorted(accepted, key=lambda item: -item[1]), rejected

def main():
    lines = sys.stdin.read().splitlines()
    n = int(lines[0])
    accepted, rejected = intake(lines[1:1 + n])
    print(len(accepted), rejected)
    for code, priority in accepted:
        print(code, priority)

