import sys

class Book:
    def __init__(self, copies):
        self.__copies = copies

    def borrow(self):
        if self.__copies == 0:
            return False
        self.__copies -= 1
        return True

    def return_copy(self):
        self.__copies += 1

    def available(self):
        return self.__copies

def main():
    lines = iter(sys.stdin.read().splitlines())
    n = int(next(lines))
    books = {}
    for _ in range(n):
        code, copies = next(lines).split()
        books[code] = Book(int(copies))
    q = int(next(lines))
    result = []
    for _ in range(q):
        action, code = next(lines).split()
        book = books.get(code)
        if book is None:
            result.append('UNKNOWN')
        elif action == 'STATUS':
            result.append(str(book.available()))
        elif action == 'BORROW':
            result.append('OK' if book.borrow() else 'EMPTY')
        else:
            book.return_copy()
            result.append('OK')
    print('\n'.join(result))

main()

import sys

class StudentRecord:
    def __init__(self):
        self.__scores = []

    def add(self, score):
        if not 0 <= score <= 100:
            return False
        self.__scores.append(score)
        return True

    def replace(self, index, score):
        if not (0 <= index < len(self.__scores) and 0 <= score <= 100):
            return False
        self.__scores[index] = score
        return True

    def average(self):
        if not self.__scores:
            return None
        return sum(self.__scores) // len(self.__scores)

def main():
    lines = sys.stdin.read().splitlines()
    q = int(lines[0])
    record = StudentRecord()
    result = []
    for line in lines[1:1 + q]:
        parts = line.split()
        if parts[0] == 'ADD':
            result.append('OK' if record.add(int(parts[1])) else 'INVALID')
        elif parts[0] == 'REPLACE':
            result.append('OK' if record.replace(int(parts[1]), int(parts[2])) else 'INVALID')
        else:
            value = record.average()
            result.append('EMPTY' if value is None else str(value))
    print('\n'.join(result))

