import sys

class Parcel:
    def __init__(self, weight):
        self.weight = weight

    def charge(self):
        raise NotImplementedError

class StandardParcel(Parcel):
    def charge(self):
        return 5 + 2 * self.weight

class ExpressParcel(Parcel):
    def charge(self):
        return 10 + 3 * self.weight

class Dispatch:
    def __init__(self):
        self.parcels = []

    def add(self, parcel):
        self.parcels.append(parcel)
        return parcel.charge()

    def total(self):
        return sum(parcel.charge() for parcel in self.parcels)

def main():
    lines = sys.stdin.read().splitlines()
    q = int(lines[0])
    dispatch = Dispatch()
    result = []
    for line in lines[1:1 + q]:
        parts = line.split()
        if parts[0] == 'TOTAL':
            result.append(str(dispatch.total()))
            continue
        weight = int(parts[2])
        parcel = StandardParcel(weight) if parts[1] == 'STANDARD' else ExpressParcel(weight)
        result.append(str(dispatch.add(parcel)))
    print('\n'.join(result))

