import sys

class MediaItem:
    def __init__(self):
        self.out = False

    def loan_days(self):
        raise NotImplementedError

class Book(MediaItem):
    def loan_days(self):
        return 21

class Video(MediaItem):
    def loan_days(self):
        return 7

class Library:
    def __init__(self):
        self.items = {}

    def add(self, code, item):
        self.items[code] = item

    def command(self, action, code):
        item = self.items.get(code)
        if item is None:
            return 'UNKNOWN'
        if action == 'LOOKUP':
            return f"{item.loan_days()} {'OUT' if item.out else 'AVAILABLE'}"
        if action == 'BORROW':
            if item.out:
                return 'OUT'
            item.out = True
            return str(item.loan_days())
        if not item.out:
            return 'AVAILABLE'
        item.out = False
        return 'OK'

def main():
    lines = iter(sys.stdin.read().splitlines())
    n = int(next(lines))
    library = Library()
    for _ in range(n):
        code, kind = next(lines).split()
        library.add(code, Book() if kind == 'BOOK' else Video())
    q = int(next(lines))
    print('\n'.join(library.command(*next(lines).split()) for _ in range(q)))

